// Writes src/styles/springs.css: the MotionScheme springs as CSS linear() easings plus their
// settle time, from src/data/shapes.json (generated by verify/shapes-svg from the material3 tokens).
import { readFileSync, writeFileSync } from 'node:fs';

const { springs } = JSON.parse(readFileSync(new URL('../src/data/shapes.json', import.meta.url)));
const lines = Object.entries(springs).map(
  ([name, s]) => `  --md-spring-${name}: ${s.linear};\n  --md-spring-${name}-ms: ${s.ms}ms;`,
);
writeFileSync(
  new URL('../src/styles/springs.css', import.meta.url),
  `/* Generated by scripts/gen-springs.mjs. Damping ratio / stiffness from ExpressiveMotionTokens and StandardMotionTokens. */\n:root {\n${lines.join('\n')}\n}\n`,
);
console.log(`wrote ${lines.length} springs`);
